SELECT x.queue, x.run, x.body,
  json_patch(json_patch('{}', json_object('item', x.item, 'repo', x.repo, 'sha', x.sha, 'mode', x.mode, 'pid_stamp', x.pid_stamp, 'pid', x.pid, 'until', x.until, 'worktree', x.worktree, 'remote', x.remote, 'branch', x.branch, 'summary', x.summary, 'enqueued_at', x.enqueued_at, 'lane', x.lane, 'slot', coalesce(x.slot, CASE WHEN coalesce(x.slot_worktree, x.slot_token) IS NOT NULL THEN json_object('worktree', x.slot_worktree, 'token', x.slot_token) END), 'no_pre', x.no_pre, 'pre', CASE WHEN coalesce(x.pre_judged, x.pre_base, x.pre_keep, x.pre_number, x.pre_group, x.pre_born_s) IS NOT NULL THEN json_object('judged', x.pre_judged, 'base', x.pre_base, 'keep', x.pre_keep, 'number', x.pre_number, 'group', x.pre_group, 'born', CASE WHEN x.pre_born_s IS NOT NULL THEN json_array(x.pre_born_s, x.pre_born_us) END) END, 'pre_carry', x.pre_carry, 'pre_verdict', CASE WHEN coalesce(x.pre_verdict, x.pre_verdict_kind, x.pre_verdict_why) IS NOT NULL THEN json_object('state', x.pre_verdict, 'kind', x.pre_verdict_kind, 'why', x.pre_verdict_why) END, 'red_last', x.red_last, 'main_red', CASE WHEN coalesce(x.main_red_sha, (SELECT 1 FROM request_nodes c WHERE c.queue = x.queue AND c.run = x.run LIMIT 1)) IS NOT NULL THEN json_object('sha', x.main_red_sha, 'nodes', json(nullif(nullif((SELECT json_group_array(c.value ORDER BY c.ord) FROM request_nodes c WHERE c.queue = x.queue AND c.run = x.run), '[]'), '{}'))) END, 'superseded', x.superseded, 'at', x.marked_at, 'pre_affected', CASE WHEN coalesce(x.pre_affected_ran, x.pre_affected_took, x.pre_affected_by, x.pre_affected_lane_s, x.pre_affected_tests) IS NOT NULL THEN json_object('ran', x.pre_affected_ran, 'took', x.pre_affected_took, 'by', x.pre_affected_by, 'lane_s', x.pre_affected_lane_s, 'tests', x.pre_affected_tests) END, 'pre_run', CASE WHEN coalesce(x.pre_run_skipped, coalesce(x.remote_outcome, x.remote_cause, x.remote_where, x.remote_host, x.remote_worker_s, x.remote_mac_s, x.remote_mac_est_s, x.remote_rerun_s, x.remote_saved_s, x.remote_t0, x.remote_tests, x.remote_fresh), x.pre_run_wait_s, x.pre_run_run_s, x.pre_run_limit_s, x.pre_run_cpu_s, x.pre_run_workers) IS NOT NULL THEN json_object('skipped', x.pre_run_skipped, 'remote', CASE WHEN coalesce(x.remote_outcome, x.remote_cause, x.remote_where, x.remote_host, x.remote_worker_s, x.remote_mac_s, x.remote_mac_est_s, x.remote_rerun_s, x.remote_saved_s, x.remote_t0, x.remote_tests, x.remote_fresh) IS NOT NULL THEN json_object('outcome', x.remote_outcome, 'cause', x.remote_cause, 'where', x.remote_where, 'host', x.remote_host, 'worker_s', x.remote_worker_s, 'mac_s', x.remote_mac_s, 'mac_est_s', x.remote_mac_est_s, 'rerun_s', x.remote_rerun_s, 'saved_s', x.remote_saved_s, 't0', x.remote_t0, 'tests', x.remote_tests, 'fresh', CASE x.remote_fresh WHEN 1 THEN json('true') WHEN 0 THEN json('false') END) END, 'wait_s', x.pre_run_wait_s, 'run_s', x.pre_run_run_s, 'limit_s', x.pre_run_limit_s, 'cpu_s', x.pre_run_cpu_s, 'workers', x.pre_run_workers) END, 'cov_risk', CASE WHEN coalesce(x.cov_said, x.cov_head, x.cov_base, x.cov_lines, (SELECT 1 FROM request_cov_carry c WHERE c.queue = x.queue AND c.run = x.run LIMIT 1), (SELECT 1 FROM request_cov_files c WHERE c.queue = x.queue AND c.run = x.run LIMIT 1)) IS NOT NULL THEN json_object('said', x.cov_said, 'head', x.cov_head, 'base', x.cov_base, 'lines', x.cov_lines, 'carry', json(nullif(nullif((SELECT json_group_array(json_patch('{}', json_object('file', c.file, 'text', c.text, 'why', c.why, 'line', c.line, 'own', CASE c.own WHEN 1 THEN json('true') WHEN 0 THEN json('false') END, 'measured', CASE c.measured WHEN 1 THEN json('true') WHEN 0 THEN json('false') END)) ORDER BY c.ord) FROM request_cov_carry c WHERE c.queue = x.queue AND c.run = x.run), '[]'), '{}')), 'files', json(nullif(nullif((SELECT json_group_object(c.path, c.said) FROM request_cov_files c WHERE c.queue = x.queue AND c.run = x.run), '[]'), '{}'))) END, 'pre_s', x.pre_s, 'slot_s', x.slot_s)), coalesce(x.rest, '{}')) AS doc
FROM early x
